insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('427750c4-de3c-5039-b398-ffe1b3e09178', 'conditions-of-use', '3.2', 3, 2, 0, '2026-09-01', 'CURRENT', true, '{"en": "# Conditions of Use\n\n## Agreement\n\nThese Conditions of Use govern your use of AfroTransact websites, apps and services. By creating an account or placing an order you agree to them. If you do not agree, do not use AfroTransact.\n\n## Who you buy from\n\nAfroTransact is a marketplace. Many items are sold by independent sellers and many services are performed by independent providers; the seller or provider is shown on every listing, order and receipt. Items “Sold by AfroTransact” are sold by AfroTransact, Inc.\n\n## Your account\n\nYou must be 18 or older, give accurate information and keep your sign-in details secure. You are responsible for activity on your account. One person may hold customer, seller and provider roles on the same account.\n\n## Prices, payment and taxes\n\nPrices are in US dollars and include any discount shown at checkout. We charge your payment method when you place an order, or a deposit when you book a service. Sales tax is calculated by delivery address and shown before you pay. Payments are processed by Stripe.\n\n## Delivery and services\n\nDelivery estimates are not guarantees. Risk of loss passes to you on delivery. Service appointments follow the provider’s cancellation policy shown before you book.\n\n## Reviews and content\n\nReviews must reflect a genuine experience. You grant AfroTransact a licence to display content you submit. We may remove content that breaks our rules.\n\n## Disputes\n\nContact customer service first; most issues are resolved within 48 hours. Any dispute not resolved informally will be settled by binding individual arbitration under the AAA Consumer Rules, except small-claims matters. You may opt out of arbitration within 30 days of accepting these terms by writing to {legal}.\n\n## Notifications, email and text messages\n\nBy creating an account you agree that AfroTransact may send transactional messages about your account, orders, deliveries, bookings, payments and security by email, push notification and, if you provide a mobile number and opt in, SMS/MMS. Marketing messages are sent only with your separate, express consent, which is never a condition of purchase. SMS program: {smsProgramName}. Message frequency varies by activity. Message and data rates may apply. Reply STOP to cancel, HELP for help, or call {phone}. Carriers are not liable for delayed or undelivered messages. Full details are in the SMS & Notification Terms.\n\n## Changes\n\nWe will give at least 30 days’ notice of material changes by email and in the app. The version and effective date appear at the top of this page.\n"}'::jsonb, 'Adds notifications, SMS and current contact details', '2026-09-01T00:00:00Z', 'seed', '2026-09-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('cf30957d-95cc-5d40-99fb-48ae84b2957c', 'conditions-of-use', '3.1', 3, 1, 0, '2026-03-15', 'ARCHIVED', true, '{"en": "# Conditions of Use (version 3.1)\n\n## Archived version\n\nVersion 3.1 of the Conditions of Use applied from 2026-03-15 until 2026-09-01, when version 3.2 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2026-03-15T00:00:00Z', 'seed', '2026-03-15T00:00:00Z', '2026-09-01T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('e98b2caa-dc06-5fa5-9119-704c0bfacef3', 'conditions-of-use', '3.0', 3, 0, 0, '2025-11-01', 'ARCHIVED', true, '{"en": "# Conditions of Use (version 3.0)\n\n## Archived version\n\nVersion 3.0 of the Conditions of Use applied from 2025-11-01 until 2026-03-15, when version 3.1 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2025-11-01T00:00:00Z', 'seed', '2025-11-01T00:00:00Z', '2026-03-15T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('abb698cb-4449-591c-810a-5c7c199687f7', 'privacy', '4.0', 4, 0, 0, '2026-09-01', 'CURRENT', true, '{"en": "# Privacy Notice\n\n## Information we collect\n\nAccount details (name, email, phone), delivery addresses, order and booking history, payment tokens from Stripe (never full card numbers), device and usage data, and messages with sellers, providers, drivers and Lola, our AI assistant.\n\n## How we use it\n\nTo process orders and bookings, deliver packages, prevent fraud, provide support, personalise recommendations, and — only with consent — send marketing and measure advertising.\n\n## Who we share it with\n\nThe seller, provider or driver handling your order receives only what they need (for example, a name and delivery address). We also share data with service providers such as Stripe, our address-verification and mapping vendors and cloud hosting, under contracts that limit their use. We do not sell personal information for money.\n\n## AI features\n\nLola processes your questions to find products and manage orders. Personal details are redacted before any model call and conversations are not used to train third-party models.\n\n## Retention\n\nWe keep order records for 7 years for tax and accounting, and other data only as long as needed for the purpose collected. Closed accounts are deleted or de-identified within 90 days, except where law requires us to keep records.\n\n## Your rights\n\nDepending on your state you may access, correct, delete or port your data and opt out of sale, sharing, targeted advertising and profiling. Use Your Privacy Choices or email {privacy}. We will not discriminate against you for exercising your rights.\n\n## Mobile numbers, SMS and notifications\n\nWe use your mobile number to send the order, delivery, booking, security (including one-time passcodes) and — only if you opted in — marketing messages you asked for, through our messaging providers (such as Twilio). No mobile information will be shared with third parties or affiliates for marketing or promotional purposes. Text-messaging originator opt-in data and consent are excluded from every sharing category in this notice and will not be shared with any third party. Reply STOP to any text to opt out; manage email and push preferences in Account → Notifications.\n\n## Children\n\nAfroTransact is not directed to children under 13 and we do not knowingly collect their data.\n\n## Security\n\nData is encrypted in transit and at rest, access is role-based and logged, and payment data is handled by PCI DSS Level 1 certified Stripe.\n\n## Contact\n\nPrivacy questions: {privacy} · {address}.\n"}'::jsonb, 'Adds notifications, SMS and current contact details', '2026-09-01T00:00:00Z', 'seed', '2026-09-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('b1a2aa43-905a-50a6-8deb-31dd35977094', 'privacy', '3.4', 3, 4, 0, '2026-01-10', 'ARCHIVED', true, '{"en": "# Privacy Notice (version 3.4)\n\n## Archived version\n\nVersion 3.4 of the Privacy Notice applied from 2026-01-10 until 2026-09-01, when version 4.0 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2026-01-10T00:00:00Z', 'seed', '2026-01-10T00:00:00Z', '2026-09-01T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('75843b71-ecc3-5369-903b-676141e36997', 'cookies', '2.1', 2, 1, 0, '2026-09-01', 'CURRENT', true, '{"en": "# Cookie Notice\n\n## What cookies are\n\nCookies and similar technologies (local storage, pixels, SDKs) store small pieces of information on your device.\n\n## How we use them\n\nWe group cookies into four categories. Strictly necessary cookies are always on; you choose the rest below. Your choice is saved for 12 months and you can change it at any time from “Cookie preferences” in the footer.\n\n## Global Privacy Control\n\nWe honour the Global Privacy Control (GPC) browser signal as an opt-out of advertising cookies and of sale and sharing.\n\n## Cookies we use\n\nThe cookie table below this notice lists every cookie and similar technology we use, with its provider, purpose, duration and category. It is generated from the same configuration as the cookie banner, so it is always current.\n"}'::jsonb, 'Adds notifications, SMS and current contact details', '2026-09-01T00:00:00Z', 'seed', '2026-09-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('9492355e-b41b-54ca-a8cb-5db417e77e11', 'cookies', '2.0', 2, 0, 0, '2026-01-10', 'ARCHIVED', true, '{"en": "# Cookie Notice (version 2.0)\n\n## Archived version\n\nVersion 2.0 of the Cookie Notice applied from 2026-01-10 until 2026-09-01, when version 2.1 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2026-01-10T00:00:00Z', 'seed', '2026-01-10T00:00:00Z', '2026-09-01T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('2a3b616e-da65-54ff-bb48-785aa66eeb22', 'privacy-choices', '1.3', 1, 3, 0, '2026-09-01', 'CURRENT', true, '{"en": "# Your Privacy Choices\n\n## Your rights\n\nYou can ask for a copy of your data, ask us to correct or delete it, and opt out of sale, sharing and targeted advertising. Authorised agents may submit requests with signed permission.\n\n## How we verify\n\nWe send a confirmation link to the email on your account. For deletion we also ask you to sign in. You can appeal a decision by replying to our response; we answer appeals within 60 days.\n"}'::jsonb, 'First draft for counsel review', '2026-09-01T00:00:00Z', 'seed', '2026-09-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('f3b2a6ba-679e-548b-9413-f8ab0fec60a0', 'returns', '2.0', 2, 0, 0, '2026-06-01', 'CURRENT', true, '{"en": "# Returns & Refunds\n\n## Return window\n\nMost items can be returned within 30 days of delivery. The window is shown on each product page and in Your orders.\n\n## Non-returnable items\n\nPerishable food, opened beauty and personal-care items, custom-made clothing and gift cards cannot be returned unless they arrive damaged, defective or not as described.\n\n## Damaged or wrong items\n\nReport within 7 days with a photo. We refund or replace at no cost and you don’t need to send perishables back.\n\n## Refunds\n\nRefunds go to the original payment method within 3–5 business days after we receive the return, or immediately for drop-off at a pickup point. ACH refunds can take up to 7 business days.\n\n## Services\n\nService refunds follow the provider’s cancellation policy shown at booking. If a provider cancels or does not show up, you get a full refund including any deposit.\n"}'::jsonb, 'Adds notifications, SMS and current contact details', '2026-06-01T00:00:00Z', 'seed', '2026-06-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('1156c2c6-55cb-559a-b900-8d2d2aa9e219', 'returns', '1.4', 1, 4, 0, '2025-12-01', 'ARCHIVED', true, '{"en": "# Returns & Refunds (version 1.4)\n\n## Archived version\n\nVersion 1.4 of the Returns & Refunds applied from 2025-12-01 until 2026-06-01, when version 2.0 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2025-12-01T00:00:00Z', 'seed', '2025-12-01T00:00:00Z', '2026-06-01T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('3fc29136-599d-51d6-bdf7-4e3037f60ef0', 'seller-terms', '2.4', 2, 4, 0, '2026-09-01', 'CURRENT', true, '{"en": "# Seller & Provider Terms\n\n## Eligibility\n\nSellers and providers must complete Stripe Connect verification and AfroTransact’s document review before going live. Licences, permits and insurance must stay current.\n\n## Fees\n\nAfroTransact charges a referral fee per sale or booking and a monthly plan fee where applicable. Current rates are shown in Seller Central and the plan page; we give 30 days’ notice of changes.\n\n## Payouts\n\nEarnings are held for at least 7 days after delivery (products) or service completion (services) so payments settle and returns or disputes can be raised. Released earnings appear as your available balance. You request payouts from your AfroTransact dashboard (minimum $25, one request per day); we review and send approved payouts by ACH to your verified bank account, normally within 1–2 business days. Payments are processed by Stripe on our behalf — you do not need a Stripe account login. We may hold specific funds while a return, dispute, chargeback or policy review is open, and unclaimed balances are paid out automatically before any legal holding limit.\n\n## Listings and conduct\n\nListings must be accurate and comply with the Prohibited & Restricted Items policy. Do not divert customers off AfroTransact or manipulate reviews.\n\n## Performance\n\nWe measure late shipments, cancellations, defects and response time. Accounts below standard may be limited or suspended after notice and a chance to appeal.\n"}'::jsonb, 'Adds notifications, SMS and current contact details', '2026-09-01T00:00:00Z', 'seed', '2026-09-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('d9de8500-4c2a-5820-a557-046eb997ca39', 'seller-terms', '2.3', 2, 3, 0, '2026-04-01', 'ARCHIVED', true, '{"en": "# Seller & Provider Terms (version 2.3)\n\n## Archived version\n\nVersion 2.3 of the Seller & Provider Terms applied from 2026-04-01 until 2026-09-01, when version 2.4 replaced it. Write to {legal} for a certified copy of the full text.\n"}'::jsonb, 'Archived', '2026-04-01T00:00:00Z', 'seed', '2026-04-01T00:00:00Z', '2026-09-01T00:00:00Z');
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('2fb20bb5-c029-504f-a7b0-944e0fd7a189', 'prohibited-items', '1.6', 1, 6, 0, '2026-07-15', 'CURRENT', true, '{"en": "# Prohibited & Restricted Items\n\n## Never allowed\n\nWeapons and ammunition, illegal drugs and paraphernalia, counterfeit goods, wildlife products protected under CITES, recalled items, and unapproved medicines or supplements making disease claims.\n\n## Restricted — approval needed\n\nAlcohol, meat and seafood, raw shea and herbal products marketed for health, cosmetics with mercury or hydroquinone, and immigration, tax or legal services. Approval requires the relevant licence or permit.\n\n## Imported food\n\nImported foods must meet FDA rules, carry English labelling and allergen information, and come from registered facilities.\n\n## Reporting\n\nReport a listing from its page or email {legal}. We review reports within one business day.\n"}'::jsonb, 'First draft for counsel review', '2026-07-15T00:00:00Z', 'seed', '2026-07-15T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('f33370f5-c7d7-598b-9153-e5786a5d4e40', 'sms-terms', '1.0', 1, 0, 0, '2026-10-10', 'CURRENT', true, '{"en": "# SMS & Notification Terms\n\n## Program\n\n{smsProgramName} is a text-message program from AfroTransact, Inc. that sends order confirmations, delivery and driver updates, booking reminders and changes, payment and refund notices, security alerts and one-time passcodes. If you separately opt in to AfroTransact Deals, we also send offers and restock alerts.\n\n## How you opt in\n\nYou opt in by entering your mobile number and ticking the SMS consent box at sign-up, checkout, booking or in Account → Notifications, or by texting START to our number. Consent to marketing texts is optional and is not a condition of any purchase. We confirm your enrolment by text.\n\n## Message frequency and cost\n\nMessage frequency varies with your orders and bookings; AfroTransact Deals sends up to 4 messages per month. Message and data rates may apply according to your mobile plan.\n\n## Opting out and help\n\nReply STOP, END, CANCEL, UNSUBSCRIBE or QUIT to any message to stop texts; you will receive one final confirmation and no further messages. Reply START to rejoin. Reply HELP or contact {phone} or {privacy} for support. Security codes requested by you will still be sent by email if you opt out of SMS.\n\n## Supported carriers\n\nSupported on major US carriers including AT&T, T-Mobile, Verizon and their MVNOs. Carriers are not liable for delayed or undelivered messages.\n\n## Push and email notifications\n\nPush notifications are controlled in your device settings and in Account → Notifications. Every marketing email includes a one-click unsubscribe link; transactional emails about orders, bookings, payments and security cannot be turned off while your account is open.\n\n## Privacy\n\nYour mobile number and SMS consent are handled under our Privacy Notice. No mobile information will be shared with third parties or affiliates for marketing or promotional purposes, and opt-in data and consent are never shared with any third party.\n\n## Quiet hours\n\nMarketing texts are sent only between 9 am and 8 pm in your local time zone. Delivery and security messages may be sent at any time.\n"}'::jsonb, 'First draft for counsel review', '2026-10-10T00:00:00Z', 'seed', '2026-10-10T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('ef97c966-5e0e-5cde-9ec9-790caefd3e19', 'accessibility', '1.2', 1, 2, 0, '2026-08-20', 'CURRENT', true, '{"en": "# Accessibility Statement\n\n## Our commitment\n\nWe aim to meet WCAG 2.2 Level AA across the AfroTransact website and apps and test with VoiceOver, TalkBack, NVDA and keyboard-only navigation.\n\n## What we support\n\nText resizing to 200%, reduced motion, high-contrast themes, captions on videos, and screen-reader labels on all controls. Seller storefront themes must meet minimum contrast before they can be published.\n\n## Known limitations\n\nSome older seller-uploaded images lack descriptive alt text; we are adding AI-suggested descriptions for sellers to review.\n\n## Feedback\n\nEmail {accessibility} or call {phone}. We respond within 2 business days.\n"}'::jsonb, 'First draft for counsel review', '2026-08-20T00:00:00Z', 'seed', '2026-08-20T00:00:00Z', null);
